package dk.starswordmaster.progression;
import org.junit.Test;
import java.math.BigInteger;
import java.util.Properties;
import static org.junit.Assert.*;
public class UnboundedProgressionTest {
 private static BigInteger n(long n){return BigInteger.valueOf(n);}
 private PlayerProgress freshAt(long xp){var p=new Properties();p.setProperty("xp",Long.toString(xp));p.setProperty("xpCurveVersion","2");p.setProperty("practice.SWORD","20");p.setProperty("practice.FIRE","20");return PlayerProgress.fromProperties(p);}
 @Test public void optionalPracticeRewardsUseStartingCharacterLevel(){var p=freshAt(909);p.awardPractice(Skill.SWORD,5,1);assertEquals(n(1009),p.totalXp());assertEquals(n(8),p.level());p.awardPractice(Skill.FIRE,5,1);assertEquals(n(1159),p.totalXp());assertEquals(n(9),p.level());assertEquals(n(40),p.statPoints());assertEquals(n(8),p.points());}
 @Test public void oneHugeAwardGrantsExactlyFiveStatsAndOnePerkPerLevel(){var p=new PlayerProgress();p.awardXp(BigInteger.TEN.pow(100));assertTrue(p.level().compareTo(n(Long.MAX_VALUE))>0);assertEquals(p.level().subtract(BigInteger.ONE).multiply(n(5)),p.statPoints());assertEquals(p.level().subtract(BigInteger.ONE),p.points());p=PlayerProgress.fromProperties(p.toProperties());var old=p.toProperties();for(int i=0;i<5;i++)p=PlayerProgress.fromProperties(p.toProperties());assertEquals(old,p.toProperties());assertTrue(Double.isFinite(p.maxMana())&&Double.isFinite(p.maxStamina()));}
 @Test public void skillMasteryKeepsTrainingWithoutDefaultCharacterXp(){var props=new Properties();props.setProperty("xp","200000");props.setProperty("practice.SWORD","245025");var p=PlayerProgress.fromProperties(props);for(int i=0;i<250;i++)p.awardPractice(Skill.SWORD,20);assertEquals(100,p.skillLevel(Skill.SWORD));assertEquals(n(200000),p.totalXp());assertEquals("250025",p.toProperties().getProperty("practice.SWORD"));}
 @Test public void migrationPreservesOldResourcesStatsPerksAndProgress(){var props=new Properties();props.setProperty("xp","200000");props.setProperty("class","MAGE");props.setProperty("practice.FIRE","10000");props.setProperty("learned","spark,mana_control");props.setProperty("stat.SPIRIT","495");props.setProperty("mana","60");props.setProperty("stamina","70");props.setProperty("slot.0","spark");var p=PlayerProgress.fromProperties(props);assertEquals(n(100),p.level());assertEquals(n(200000),p.totalXp());assertEquals(495,p.stat(PlayerProgress.Stat.SPIRIT));assertEquals(n(0),p.statPoints());assertEquals(n(97),p.points());assertEquals(2793,p.maxMana(),0);assertEquals(60,p.mana(),0);assertEquals(70,p.stamina(),0);assertEquals("spark",p.slot(0));assertEquals(p.toProperties(),PlayerProgress.fromProperties(p.toProperties()).toProperties());p.awardXp(n(1400));assertEquals(n(101),p.level());assertEquals(n(5),p.statPoints());assertEquals(n(98),p.points());}
 @Test public void invalidLargeStatAllocationsNeverWrapOrSpendWithoutChange(){var props=new Properties();props.setProperty("xpCurveVersion","2");props.setProperty("xp",BigInteger.TEN.pow(30).toString());props.setProperty("stat.ENDURANCE",Integer.toString(Integer.MAX_VALUE));var p=PlayerProgress.fromProperties(props);var points=p.statPoints();assertFalse(p.spendStat(PlayerProgress.Stat.ENDURANCE));assertEquals(points,p.statPoints());assertEquals(5L*Integer.MAX_VALUE,p.enduranceStaminaBonus());assertEquals(Integer.MAX_VALUE,p.stat(PlayerProgress.Stat.ENDURANCE));}
}
